const fs = require("fs");
const html = fs.readFileSync("app/index.html", "utf8");
// Check void tags vs normal tags
const voidTags = new Set(["area","base","br","col","embed","hr","img","input","link","meta","param","source","track","wbr"]);
const tagRegex = /<\/?([a-zA-Z0-9\-]+)[^>]*>/g;
const stack = [];
let match;
while ((match = tagRegex.exec(html)) !== null) {
  const full = match[0];
  const tag = match[1].toLowerCase();
  if (full.startsWith("<!--") || full.endsWith("/>") || voidTags.has(tag)) continue;
  if (full.startsWith("</")) {
    const expected = stack.pop();
    if (expected !== tag) {
      console.warn("Mismatched tag: expected </" + expected + ">, got </" + tag + ">");
    }
  } else {
    stack.push(tag);
  }
}
console.log("Unclosed stack length:", stack.length, stack);
